create or replace function average_unit_cost(p_sku in varchar2) return number is
  -- Weighted average purchase cost per unit over all goods receipts of an item.
  l_total_cost number := 0;
  l_total_qty number := 0;
  l_cost number;
begin
  select sum(total_cost) into l_total_cost
    from goods_receipts
   where sku = p_sku;

  select sum(quantity) into l_total_qty
    from goods_receipts
   where sku = p_sku;

  if l_total_qty > 0 then
    l_cost := l_total_cost / l_total_qty;
  else
    l_cost := 0;
  end if;

  return l_cost;
end average_unit_cost;
/
